from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")
        if end <= start:
            raise ValueError("Appointment end must be after start.")
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if appt["cancelled"]:
                continue
            if _overlaps(start, end, appt["start"], appt["end"]):
                raise ValueError("Appointment overlaps an existing booking.")
        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "id": appt_id,
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError(f"No appointment with id {appointment_id}")
        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return
        # Cancelling less than 24 hours before start keeps the slot blocked
        if now < appt["start"] - timedelta(hours=24):
            appt["cancelled"] = True
        else:
            appt["cancelled"] = True
            appt["slot_blocked"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if appt["cancelled"] and not appt.get("slot_blocked"):
                continue
            if _overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True


def _overlaps(s1: datetime, e1: datetime, s2: datetime, e2: datetime) -> bool:
    # Touching intervals (e1 == s2 or e2 == s1) do not overlap
    return s1 < e2 and s2 < e1
